     1275:         if (TIFFFieldSet(tif, FIELD_SUBIFD) && (tif->tif_subifdoff == 0))
     1276:         {
     1277:             uint32_t na;
     1278:             TIFFDirEntry *nb;
     1279:             for (na = 0, nb = dir;; na++, nb++)
     1280:             {
     1281:                 if (na == ndir)
     1282:                 {
     1283:                     TIFFErrorExtR(tif, module, "Cannot find SubIFD tag");
     1284:                     goto bad;
     1285:                 }
     1286:                 if (nb->tdir_tag == TIFFTAG_SUBIFD)
     1287:                     break;
     1288:             }
     1289:             if (!(tif->tif_flags & TIFF_BIGTIFF))
     1290:                 tif->tif_subifdoff = tif->tif_diroff + 2 + na * 12 + 8;
     1291:             else
