>>>  1297:     dirmem = _TIFFmallocExt(tif, dirsize);
     1298:     if (dirmem == NULL)
     1299:     {
     1300:         TIFFErrorExtR(tif, module, "Out of memory");
     1301:         goto bad;
     1302:     }
