     1307:         TIFFDirEntry *o;
     1308:         n = (uint8_t *)dirmem;
     1309:         *(uint16_t *)n = (uint16_t)ndir;
     1310:         if (tif->tif_flags & TIFF_SWAB)
     1311:             TIFFSwabShort((uint16_t *)n);
     1312:         n += 2;
     1313:         o = dir;
     1314:         for (m = 0; m < ndir; m++)
     1315:         {
     1316:             *(uint16_t *)n = o->tdir_tag;
     1317:             if (tif->tif_flags & TIFF_SWAB)
     1318:                 TIFFSwabShort((uint16_t *)n);
