     1325:             _TIFFmemcpy(n, &nTmp, 4);
     1326:             if (tif->tif_flags & TIFF_SWAB)
     1327:                 TIFFSwabLong((uint32_t *)n);
     1328:             n += 4;
     1329:             /* This is correct. The data has been */
     1330:             /* swabbed previously in TIFFWriteDirectoryTagData */
     1331:             _TIFFmemcpy(n, &o->tdir_offset, 4);
     1332:             n += 4;
